 reviews.append(dict(id=q['id']+'-v1-contracts-independent',questionId=q['id'],questionVersion=q['version'],questionSha256=question_hash(q),reviewerId=R,decision='flagged' if q['id'] in flags else 'verified',reviewedAt=now,sourceVersions={'lectures':e['sourceSha256']},reviewedSlideIds=[f'lectures-p{p:04}' for p in pages],independentAnswerOptionIds=a['independentAnswerOptionIds'],solvedBeforeAnswerSeen=True,checks=checks,reasoning=reason,findings=[msg for _,msg in flags.get(q['id'],[])],blindAnswersPath=ap,blindAnswersSha256=sha(ap),independentSolvedAt=e['frozenAt'],priorAuthorExposure=False,sourceAnswerExposure='Printed source statements and worked examples were visible during source-first solving; no question-author keys or solutions were exposed.',computationsPath='audits/W04-L16-independent-checks.json',sourceInspectionEvidence=[dict(inspectorId=R,**{k:obs[p][k] for k in ['physicalPage','previewPath','previewSha256','dimensions','inspectedAt']}) for p in pages]))
